  ('youtube-channel-strategist', 'YouTube Channel Strategist', 'A complete YouTube growth plan: niche and positioning, 30 video ideas with titles and hooks, upload schedule, SEO and monetisation steps.', 'Content Creation', ARRAY['YouTube', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
