  ('book-cover-designer', 'Book Cover Designer', 'Design ebook and print book covers in different genres and styles, with front cover art, a 3D mock-up and a social banner.', 'Content Creation', ARRAY['Books', 'Design'], 'featured', true, false, false, NULL, 0, ARRAY['AI Image Generation', 'Writing & Editors']),
