  ('old-photo-restoration', 'Old Photo Restoration', 'Restore old family photos: fix tears, scratches and fading, sharpen faces gently, and add natural colour to black and white pictures.', 'Photo Enhance & Retouch', ARRAY['Photo Restoration', 'Image Editing'], 'featured', true, false, false, NULL, 0, ARRAY['Personal']),
